CREATE TABLE fin_lock (id INTEGER PRIMARY KEY); INSERT INTO fin_lock VALUES (1);
CREATE TABLE fin_account (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, kind VARCHAR(12) NOT NULL CHECK(kind IN ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE')));
CREATE TABLE fin_period (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, currency VARCHAR(3) NOT NULL, state VARCHAR(8) NOT NULL CHECK(state IN ('OPEN','CLOSED')), CHECK(ends_on>starts_on));
CREATE TABLE fin_journal (id UUID PRIMARY KEY, period_id UUID NOT NULL REFERENCES fin_period(id), booked_on DATE NOT NULL, reference VARCHAR(120) UNIQUE NOT NULL, source_type VARCHAR(20) NOT NULL, source_id UUID NOT NULL, description VARCHAR(1000) NOT NULL, actor VARCHAR(160) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(source_type,source_id));
CREATE TABLE fin_entry (journal_id UUID NOT NULL REFERENCES fin_journal(id), sequence_no INTEGER NOT NULL, account_id UUID NOT NULL REFERENCES fin_account(id), debit NUMERIC(19,2) NOT NULL CHECK(debit>=0), credit NUMERIC(19,2) NOT NULL CHECK(credit>=0), PRIMARY KEY(journal_id,sequence_no), CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
CREATE TABLE fin_invoice (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, kind VARCHAR(8) NOT NULL CHECK(kind IN ('SALE','PURCHASE')), party_reference VARCHAR(160) NOT NULL, document_reference VARCHAR(160) NOT NULL, currency VARCHAR(3) NOT NULL, net NUMERIC(19,2) NOT NULL CHECK(net>0), tax NUMERIC(19,2) NOT NULL CHECK(tax>=0), total NUMERIC(19,2) NOT NULL, due_on DATE NOT NULL, control_account UUID NOT NULL REFERENCES fin_account(id), net_account UUID NOT NULL REFERENCES fin_account(id), tax_account UUID REFERENCES fin_account(id), journal_id UUID REFERENCES fin_journal(id), state VARCHAR(12) NOT NULL CHECK(state IN ('DRAFT','POSTED')), UNIQUE(kind,party_reference,document_reference));
CREATE TABLE fin_payment (id UUID PRIMARY KEY, invoice_id UUID NOT NULL REFERENCES fin_invoice(id), amount NUMERIC(19,2) NOT NULL CHECK(amount>0), external_reference VARCHAR(160) UNIQUE NOT NULL, journal_id UUID NOT NULL REFERENCES fin_journal(id));
CREATE TABLE fin_budget (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, period_id UUID NOT NULL REFERENCES fin_period(id), amount NUMERIC(19,2) NOT NULL CHECK(amount>0));
CREATE TABLE fin_expense (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, budget_id UUID NOT NULL REFERENCES fin_budget(id), amount NUMERIC(19,2) NOT NULL CHECK(amount>0), description VARCHAR(1000) NOT NULL, source_work_order UUID REFERENCES ops_work_order(id), state VARCHAR(12) NOT NULL CHECK(state IN ('DRAFT','APPROVED','POSTED','CANCELLED')), created_by VARCHAR(160) NOT NULL, approved_by VARCHAR(160), journal_id UUID REFERENCES fin_journal(id));
CREATE TABLE fin_lot_value (lot_id UUID PRIMARY KEY REFERENCES mfg_lot(id), currency VARCHAR(3) NOT NULL, unit_cost NUMERIC(19,6) NOT NULL CHECK(unit_cost>=0), evidence VARCHAR(1000) NOT NULL);
CREATE TABLE fin_cost (id UUID PRIMARY KEY, order_id UUID UNIQUE NOT NULL REFERENCES mfg_order(id), currency VARCHAR(3) NOT NULL, material_cost NUMERIC(19,2) NOT NULL, allocated_cost NUMERIC(19,2) NOT NULL, total NUMERIC(19,2) NOT NULL, unit_cost NUMERIC(19,6) NOT NULL, output_qty NUMERIC(19,6) NOT NULL, snapshot TEXT NOT NULL);
CREATE TABLE fin_allocation (id UUID PRIMARY KEY, cost_id UUID NOT NULL REFERENCES fin_cost(id), source_type VARCHAR(12) NOT NULL CHECK(source_type IN ('EXPENSE','PAYROLL')), source_id UUID NOT NULL, amount NUMERIC(19,2) NOT NULL CHECK(amount>0));
CREATE TABLE fin_scrap (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, lot_id UUID NOT NULL REFERENCES mfg_lot(id), kg NUMERIC(19,6) NOT NULL CHECK(kg>0), remaining_kg NUMERIC(19,6) NOT NULL CHECK(remaining_kg>=0), classification VARCHAR(160) NOT NULL, reason VARCHAR(1000) NOT NULL);
CREATE TABLE fin_recovery (id UUID PRIMARY KEY, scrap_id UUID NOT NULL REFERENCES fin_scrap(id), input_kg NUMERIC(19,6) NOT NULL CHECK(input_kg>0), recovered_kg NUMERIC(19,6) NOT NULL CHECK(recovered_kg>0), loss_kg NUMERIC(19,6) NOT NULL CHECK(loss_kg>=0), output_lot_id UUID UNIQUE NOT NULL REFERENCES mfg_lot(id), disposition_reference VARCHAR(160) NOT NULL, CHECK(input_kg=recovered_kg+loss_kg));
CREATE TABLE fin_audit (id UUID PRIMARY KEY, entity_id UUID NOT NULL, action VARCHAR(80) NOT NULL, actor VARCHAR(160) NOT NULL, details TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX ix_fin_allocation_source ON fin_allocation(source_type,source_id);
